insert into public.species (slug, name, latin, category_id, kind, difficulty, temperament, description, facts, keywords, is_rare, care_notice, range_areas, name_note, status)
values
('pseudocrenilabrus-multicolor','Mısır Ağızda Kuluçkacısı','Pseudocrenilabrus multicolor','afrika-nehir','fish','Kolay','Üremede bölgeci','Nil havzasından gelen, erkeklerinde metalik mavi-yeşil pullar ve kırmızı uçlu anal yüzgeç bulunan küçük bir cichlid. Dişi yumurtaları ve yavruları ağzında taşır; dayanıklı ve kolay ürer.','[["Yetişkin boy", "7–8 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; erkekler üremede bölgeci"], ["Beslenme", "Hepçil: granül, donuk yem"], ["Üreme", "Ağızda kuluçka (dişi)"], ["Köken", "Mısır, Sudan, Doğu Afrika (Nil ve Victoria havzası)"], ["Ömür", "5 yıl"], ["Özellikler", "Ağızda kuluçka, dayanıklı"]]'::jsonb,array['egyptian mouthbrooder','mısır ağızda kuluçkacı','pseudocrenilabrus multicolor','multicolor','pseudocrenilabrus']::text[],false,'','[{"r": 900, "lat": 15, "lng": 31, "label": "Nil havzası"}, {"r": 400, "lat": -1, "lng": 33, "label": "Victoria Gölü havzası"}]'::jsonb,null,'published'),
('pseudocrenilabrus-philander','Philander Ağızda Kuluçkacısı','Pseudocrenilabrus philander','afrika-nehir','fish','Kolay','Erkekler bölgeci','Güney Afrika''nın nehirlerinden, erkeklerinde turuncu-kırmızı dudak ve parlak mavi-yeşil gövdeyle dikkat çeken bir ağızda kuluçkacı. Geniş sıcaklık aralığına dayanıklıdır.','[["Yetişkin boy", "10–11 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.5–8.5"], ["Min. akvaryum", "100 L"], ["Huy", "Erkekler bölgeci; 1 erkek + birkaç dişi"], ["Beslenme", "Hepçil: granül, donuk ve canlı yem"], ["Üreme", "Ağızda kuluçka (dişi)"], ["Köken", "Güney ve Orta Afrika (Zambezi, Limpopo, Okavango)"], ["Ömür", "5–7 yıl"], ["Özellikler", "Renkli dudaklar, dayanıklı"]]'::jsonb,array['philander','pseudocrenilabrus philander','southern mouthbrooder','pseudocrenilabrus']::text[],false,'','[{"r": 1000, "lat": -18, "lng": 26, "label": "Zambezi, Okavango ve Limpopo havzaları"}]'::jsonb,null,'published'),
('nanochromis-transvestitus','Nanochromis transvestitus','Nanochromis transvestitus','afrika-nehir','fish','Zor','Barışçıl, çift','Mai-Ndombe Gölü''nün çok yumuşak, asidik siyah sularına özgü küçük bir cichlid. Adını, dişilerinin erkeklerden daha renkli ve gösterişli olmasından alır.','[["Yetişkin boy", "Erkek 5–6 cm, dişi 4 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "4.5–6.0"], ["Min. akvaryum", "54 L"], ["Huy", "Barışçıl; çift hâlinde"], ["Beslenme", "Etçil: küçük canlı ve donuk yemler"], ["Üreme", "Mağarada yumurtlayan; çift bakar"], ["Köken", "KDC, Mai-Ndombe Gölü"], ["Ömür", "4–5 yıl"], ["Özellikler", "Dişi daha renkli, siyah su"]]'::jsonb,array['nanochromis transvestitus','transvestitus','nanochromis','kongo cüce ciklit']::text[],true,'Çok yumuşak (GH 1–3) ve asidik su şart; sert suda kısa sürede hastalanır.','[{"r": 120, "lat": -2, "lng": 18.3, "label": "Mai-Ndombe Gölü"}]'::jsonb,null,'published'),
('steatocranus-casuarius','Bufalo Başlı Ciklit (Buffalohead)','Steatocranus casuarius','afrika-nehir','fish','Orta','Bölgeci, çift','Erkeklerinin alnında yaşla büyüyen yağ tümseğiyle tanınan, Kongo Nehri''nin hızlı akıntılı bölümlerinden gelen bir cichlid. Yüzme kesesi körelmiş olduğundan zıplayarak dipte hareket eder.','[["Yetişkin boy", "Erkek 11–14 cm, dişi 8 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "120 L"], ["Huy", "Tür içi bölgeci; çift hâlinde"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Mağarada yumurtlayan; çift bakar"], ["Köken", "KDC, aşağı Kongo Nehri"], ["Ömür", "8–10 yıl"], ["Özellikler", "Alın tümseği, reofilik"]]'::jsonb,array['buffalohead','bufalo başlı','steatocranus casuarius','steatocranus','lionhead cichlid','aslan başlı ciklit']::text[],false,'Akıntılı, oksijeni bol su ve bol mağara ister. Kumu kazıp düzeni değiştirir.','[{"r": 250, "lat": -4.6, "lng": 15, "label": "Aşağı Kongo Nehri (Malebo Havuzu çevresi)"}]'::jsonb,null,'published'),
('hypselecara-temporalis','Çikolata Ciklit (Chocolate Cichlid)','Hypselecara temporalis','guney-amerika','fish','Orta','Barışçıl–orta','Yaşla birlikte kırmızı-kahve tonlara bürünen, gövdesinde koyu bir leke taşıyan iri ama sakin bir Amazon ciklidi. Yumuşak su ve yaprak dökümü olan loş ortamları sever.','[["Yetişkin boy", "25–30 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "400 L"], ["Huy", "Barışçıl–orta; üremede bölgeci"], ["Beslenme", "Hepçil: granül, donuk yem, sebze"], ["Üreme", "Yumurtlayan (düz yüzey); çift bakar"], ["Köken", "Peru, Brezilya, Kolombiya (Amazon havzası)"], ["Ömür", "10–15 yıl"], ["Özellikler", "Renk değiştiren iri ciklit"]]'::jsonb,array['chocolate cichlid','çikolata ciklit','hypselecara temporalis','temporalis','hypselecara']::text[],false,'','[{"r": 900, "lat": -4, "lng": -65, "label": "Orta ve batı Amazon havzası"}]'::jsonb,null,'published'),
('hoplarchus-psittacus','Papağan Ciklit (Hoplarchus psittacus)','Hoplarchus psittacus','guney-amerika','fish','Zor','Barışçıl–orta','Rio Negro''nun siyah sularından, yaşla yeşil-mavi gövde ve kırmızı göğüs renklerine bürünen iri bir ciklit. Hobideki yapay "kan papağan" ile hiçbir ilgisi yoktur; çok yumuşak ve asidik su ister.','[["Yetişkin boy", "30–35 cm"], ["Sıcaklık", "27–31 °C"], ["pH", "4.5–6.5"], ["Min. akvaryum", "500 L"], ["Huy", "Barışçıl–orta"], ["Beslenme", "Hepçil: granül, donuk yem, sebze"], ["Üreme", "Yumurtlayan; çift bakar"], ["Köken", "Brezilya ve Venezuela (Rio Negro, Orinoco)"], ["Ömür", "10–15 yıl"], ["Özellikler", "Siyah su, iri ciklit"]]'::jsonb,array['true parrot cichlid','papağan ciklit','hoplarchus psittacus','psittacus','hoplarchus']::text[],true,'Hobide satılan "papağan balığı" (blood parrot) ile karıştırılmamalı; o yapay bir melezdir.','[{"r": 500, "lat": -1, "lng": -63, "label": "Rio Negro"}, {"r": 300, "lat": 4, "lng": -67, "label": "Orinoco havzası"}]'::jsonb,null,'published'),
('cichla-temensis','Benekli Tavus Levreği (Speckled Peacock Bass)','Cichla temensis','guney-amerika','fish','Zor','Yırtıcı','Güney Amerika''nın en büyük ciklitlerinden; doğada 80 cm''yi aşabilen, sportif balıkçılıkta ünlü bir yırtıcı. Akvaryumda yalnızca çok büyük tanklarda tutulabilir.','[["Yetişkin boy", "60–80 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "2000 L+"], ["Huy", "Yırtıcı; ağzına sığanı yer"], ["Beslenme", "Etçil: balık eti, karides, iri pelet"], ["Üreme", "Yumurtlayan; çift bakar"], ["Köken", "Brezilya, Venezuela, Kolombiya (Rio Negro, Orinoco)"], ["Ömür", "15+ yıl"], ["Özellikler", "Dev yırtıcı ciklit"]]'::jsonb,array['peacock bass','tavus levreği','cichla temensis','cichla','tucunaré']::text[],false,'Çok hızlı büyür; ev akvaryumu için uygun değildir. Doğaya bırakılmamalı.','[{"r": 600, "lat": 0, "lng": -64, "label": "Rio Negro ve Orinoco havzası"}]'::jsonb,null,'published'),
('cichla-kelberi','Sarı Tavus Levreği (Cichla kelberi)','Cichla kelberi','guney-amerika','fish','Zor','Yırtıcı','Sarı gövdesi ve gözlü kuyruk lekesiyle tanınan, Tocantins-Araguaia havzasından gelen bir tavus levreği. Cichla türleri içinde akvaryuma en çok gelenlerden biridir ama yine de çok büyük tank ister.','[["Yetişkin boy", "40–50 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "1000 L"], ["Huy", "Yırtıcı; ağzına sığanı yer"], ["Beslenme", "Etçil: balık eti, karides, iri pelet"], ["Üreme", "Yumurtlayan; çift bakar"], ["Köken", "Brezilya, Tocantins–Araguaia havzası"], ["Ömür", "10–15 yıl"], ["Özellikler", "Gözlü kuyruk lekesi"]]'::jsonb,array['yellow peacock bass','cichla kelberi','kelberi','cichla','peacock bass','tavus levreği']::text[],false,'Çok hızlı büyür; doğaya bırakılmamalı (birçok ülkede istilacı hâle gelmiştir).','[{"r": 600, "lat": -10, "lng": -49, "label": "Tocantins–Araguaia havzası"}]'::jsonb,null,'published'),
('satanoperca-lilith','Satanoperca lilith','Satanoperca lilith','guney-amerika','fish','Orta','Barışçıl, grup','Gövdesinin ortasında tek büyük koyu lekesi bulunan, kumu eleyerek beslenen bir "şeytan balığı". Rio Negro ve çevresindeki siyah sulardan gelir; sakin, grup hâlinde yaşar.','[["Yetişkin boy", "20–25 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "300 L"], ["Huy", "Barışçıl; 4+ grup"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan; ağızda kuluçka"], ["Köken", "Brezilya, orta Amazon ve Rio Negro"], ["Ömür", "10 yıl"], ["Özellikler", "Kum eleyen, tek leke"]]'::jsonb,array['satanoperca lilith','lilith','satanoperca','eartheater','şeytan balığı']::text[],false,'İnce kum zemin şart; solungaçlarından kumu eleyerek beslenir.','[{"r": 500, "lat": -2.5, "lng": -62, "label": "Orta Amazon ve Rio Negro"}]'::jsonb,null,'published'),
('geophagus-steindachneri','Kırmızı Kamburlu Geophagus (Red Hump)','Geophagus steindachneri','guney-amerika','fish','Orta','Erkekler bölgeci','Erkeklerinin alnında kırmızı bir kambur oluşan, Kolombiya ve Venezuela''dan gelen bir Geophagus. Diğer Geophagus türlerinden farklı olarak sert suya daha dayanıklıdır; dişi yumurtaları ağzında taşır.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "200 L"], ["Huy", "Erkekler bölgeci; 1 erkek + birkaç dişi"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Ağızda kuluçka (dişi)"], ["Köken", "Kolombiya ve Venezuela (Magdalena havzası)"], ["Ömür", "8–10 yıl"], ["Özellikler", "Kırmızı alın kamburu"]]'::jsonb,array['red hump eartheater','red hump geophagus','geophagus steindachneri','steindachneri','geophagus']::text[],false,'','[{"r": 400, "lat": 8, "lng": -74.5, "label": "Magdalena havzası"}]'::jsonb,null,'published'),
('gymnogeophagus-balzanii','Gymnogeophagus balzanii','Gymnogeophagus balzanii','guney-amerika','fish','Orta','Barışçıl','Erkeklerinde yaşla belirginleşen yüksek alın ve parlak mavi-sarı beneklerle tanınan, serin suya dayanıklı bir Paraná ciklidi. Yaz-kış sıcaklık farkı yaşadığı için serin bir kış dönemi ister.','[["Yetişkin boy", "15–20 cm"], ["Sıcaklık", "18–26 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl; üremede bölgeci"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Ağızda kuluçka (dişi)"], ["Köken", "Paraguay, Arjantin, Brezilya (Paraná–Paraguay havzası)"], ["Ömür", "8–10 yıl"], ["Özellikler", "Serin suya dayanıklı"]]'::jsonb,array['gymnogeophagus balzanii','balzanii','gymnogeophagus','argentine humphead']::text[],false,'Yıl boyu yüksek sıcaklıkta tutulursa ömrü kısalır; kışın 18–20 °C''lik serin bir dönem önerilir.','[{"r": 600, "lat": -22, "lng": -58, "label": "Paraná–Paraguay havzası"}]'::jsonb,null,'published'),
('mayaheros-urophthalmus','Mayan Ciklit','Mayaheros urophthalmus','orta-amerika','fish','Orta','Saldırgan','Kuyruk sapındaki gözlü leke ve gövdesindeki dikey bantlarla tanınan, Yucatán ve çevresinden gelen dayanıklı bir ciklit. Acı suya da dayanabilir; üreme döneminde çok saldırgan olur.','[["Yetişkin boy", "25–30 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "400 L"], ["Huy", "Saldırgan; üremede çok bölgeci"], ["Beslenme", "Hepçil: granül, donuk yem, sebze"], ["Üreme", "Yumurtlayan; çift bakar"], ["Köken", "Meksika (Yucatán), Belize, Guatemala, Honduras"], ["Ömür", "10+ yıl"], ["Özellikler", "Tatlı ve acı suya dayanıklı"]]'::jsonb,array['mayan cichlid','mayan ciklit','mayaheros urophthalmus','cichlasoma urophthalmus','urophthalmus']::text[],false,'Florida''da istilacı hâle gelmiştir; doğaya bırakılmamalı.','[{"r": 500, "lat": 19, "lng": -89.5, "label": "Yucatán Yarımadası ve çevresi"}]'::jsonb,'Eski adı Cichlasoma urophthalmum; hobide hâlâ bu adla geçebilir.','published'),
('cryptoheros-myrnae','Cryptoheros myrnae','Cryptoheros myrnae','orta-amerika','fish','Kolay','Üremede bölgeci','Kosta Rika ve Panama''nın Atlantik kıyısındaki nehirlerden, sarı-yeşil gövdesi ve turuncu yüzgeç kenarlarıyla dikkat çeken küçük bir Orta Amerika ciklidi. Convict''e göre daha sakindir.','[["Yetişkin boy", "10–12 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "120 L"], ["Huy", "Üremede bölgeci"], ["Beslenme", "Hepçil: granül, sebze, donuk yem"], ["Üreme", "Mağarada yumurtlayan; çift bakar"], ["Köken", "Kosta Rika ve Panama (Atlantik kıyısı)"], ["Ömür", "8–10 yıl"], ["Özellikler", "Küçük, renkli Orta Amerika ciklidi"]]'::jsonb,array['cryptoheros myrnae','myrnae','cryptoheros','amatitlania myrnae']::text[],false,'','[{"r": 200, "lat": 10, "lng": -83.5, "label": "Kosta Rika ve Panama Atlantik kıyısı"}]'::jsonb,'Bazı kaynaklarda Amatitlania myrnae olarak geçer.','published'),
('chalinochromis-brichardi','Chalinochromis brichardi','Chalinochromis brichardi','tanganyika','fish','Orta','Çift hâlinde, bölgeci','Kum rengi gövdesi ve yüzündeki koyu "gözlük" çizgileriyle tanınan, kayalık kıyılarda yaşayan bir Tanganyika ciklidi. Çiftler kalıcı bağ kurar ve mağaralarda ürer.','[["Yetişkin boy", "10–12 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "8.0–9.0"], ["Min. akvaryum", "150 L"], ["Huy", "Çift hâlinde; tür içi bölgeci"], ["Beslenme", "Hepçil: granül, donuk yem"], ["Üreme", "Mağarada yumurtlayan; çift bakar"], ["Köken", "Tanganyika Gölü (kuzey ve orta kıyılar)"], ["Ömür", "8–10 yıl"], ["Özellikler", "Yüz maskesi"]]'::jsonb,array['chalinochromis brichardi','chalinochromis','brichardi']::text[],false,'','[{"r": 250, "lat": -6, "lng": 29.8, "label": "Tanganyika Gölü orta kıyıları"}]'::jsonb,null,'published'),
('lepidiolamprologus-attenuatus','Lepidiolamprologus attenuatus','Lepidiolamprologus attenuatus','tanganyika','fish','Orta','Yırtıcı, bölgeci','İnce uzun gövdeli, gövdesinde koyu bant sıraları bulunan bir Tanganyika yırtıcısı. Küçük balıkları avlar; çift hâlinde tutulur ve üremede bölgeci olur.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "8.0–9.0"], ["Min. akvaryum", "250 L"], ["Huy", "Yırtıcı; tür içi bölgeci"], ["Beslenme", "Etçil: küçük balık, karides, donuk yem"], ["Üreme", "Mağarada yumurtlayan; çift bakar"], ["Köken", "Tanganyika Gölü"], ["Ömür", "8–10 yıl"], ["Özellikler", "İnce uzun yırtıcı"]]'::jsonb,array['lepidiolamprologus attenuatus','attenuatus','lepidiolamprologus','lamprologus attenuatus']::text[],false,'','[{"r": 400, "lat": -6.5, "lng": 29.8, "label": "Tanganyika Gölü"}]'::jsonb,'Eski adı Lamprologus attenuatus.','published'),
('lamprichthys-tanganicanus','Tanganyika Killifişi (Lamprichthys)','Lamprichthys tanganicanus','killifishler','fish','Orta','Barışçıl, sürü','Tanganyika Gölü''ne özgü, açık sularda sürü hâlinde yaşayan gümüşi-mavi parlak bir lampeye killifişi; dünyanın en büyük lampeye türüdür. Yumurtalarını kaya yarıklarına bırakır.','[["Yetişkin boy", "12–15 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "8.0–9.0"], ["Min. akvaryum", "300 L"], ["Huy", "Barışçıl; 6+ sürü"], ["Beslenme", "Hepçil: granül, donuk ve canlı yem"], ["Üreme", "Yumurtlayan (kaya yarıklarına)"], ["Köken", "Tanganyika Gölü"], ["Ömür", "3–5 yıl"], ["Özellikler", "Gölün açık su killisi"]]'::jsonb,array['lamprichthys','lamprichthys tanganicanus','tanganyika killi','tanganyika lampeye','killifish']::text[],false,'','[{"r": 400, "lat": -6.5, "lng": 29.8, "label": "Tanganyika Gölü"}]'::jsonb,null,'published'),
('copella-arnoldi','Sıçrayan Tetra (Splash Tetra)','Copella arnoldi','characiformlar','fish','Orta','Barışçıl, sürü','Yumurtalarını suyun dışına, yaprakların alt yüzüne zıplayarak bırakmasıyla ünlü bir karasin. Erkek, yumurtalar kurumasın diye kuyruğuyla saatlerce su sıçratır.','[["Yetişkin boy", "6–8 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 6+ sürü"], ["Beslenme", "Hepçil: küçük granül, donuk ve canlı yem"], ["Üreme", "Su dışına yumurtlar; erkek su sıçratır"], ["Köken", "Guyana, Surinam, Fransız Guyanası, Brezilya (Amazon ağzı)"], ["Ömür", "3–5 yıl"], ["Özellikler", "Suyun dışına yumurtlar"]]'::jsonb,array['splash tetra','sıçrayan tetra','copella arnoldi','copella','arnoldi']::text[],false,'Kapak şart; zıplar. Su seviyesi ile kapak arasında birkaç cm boşluk bırakılmalı.','[{"r": 500, "lat": 4, "lng": -55, "label": "Guyana kıyıları ve Amazon ağzı"}]'::jsonb,null,'published')
insert into public.species (slug, name, latin, category_id, kind, difficulty, temperament, description, facts, keywords, is_rare, care_notice, range_areas, name_note, status)
values
('hyphessobrycon-pyrrhonotus','Kırmızı Sırtlı Kanlı Kalp Tetra','Hyphessobrycon pyrrhonotus','characiformlar','fish','Orta','Barışçıl, sürü','Kanlı kalp tetraya benzeyen ama sırtında kırmızı bir şerit ve gövdesinde mavimsi parıltı bulunan, Rio Negro''dan gelen bir tetra. Yumuşak, asidik su ister.','[["Yetişkin boy", "5–6 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl; 8+ sürü"], ["Beslenme", "Hepçil: mikro granül, donuk ve canlı yem"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Brezilya, Rio Negro havzası"], ["Ömür", "4–6 yıl"], ["Özellikler", "Kırmızı sırt şeridi"]]'::jsonb,array['red back bleeding heart','hyphessobrycon pyrrhonotus','pyrrhonotus','kanlı kalp tetra','tetra']::text[],false,'','[{"r": 300, "lat": -0.5, "lng": -64, "label": "Rio Negro havzası"}]'::jsonb,null,'published'),
('hyphessobrycon-socolofi','Küçük Kanlı Kalp Tetra','Hyphessobrycon socolofi','characiformlar','fish','Kolay','Barışçıl, sürü','Gövdesindeki kırmızı "kalp" lekesi ve mavi parıltısıyla bilinen, Rio Negro havzasından gelen küçük bir tetra. Kanlı kalp tetranın (H. erythrostigma) daha küçük akrabasıdır.','[["Yetişkin boy", "4–5 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 8+ sürü"], ["Beslenme", "Hepçil: mikro granül, donuk ve canlı yem"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Brezilya, Rio Negro havzası"], ["Ömür", "4–5 yıl"], ["Özellikler", "Kırmızı kalp lekesi"]]'::jsonb,array['lesser bleeding heart','socolofi','hyphessobrycon socolofi','kanlı kalp tetra','tetra']::text[],false,'','[{"r": 300, "lat": -0.5, "lng": -64, "label": "Rio Negro havzası"}]'::jsonb,null,'published'),
('carnegiella-marthae','Siyah Kanatlı Balta Balığı','Carnegiella marthae','characiformlar','fish','Orta','Barışçıl, sürü; ürkek','Göğüs kısmı balta gibi derin, gümüşi gövdeli ve yüzgeçleri siyah kenarlı, en küçük balta balıklarından biri. Yüzeyde yaşar; tehlikede sudan sıçrayıp göğüs yüzgeçleriyle kısa mesafe "uçar".','[["Yetişkin boy", "3–3.5 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–6.5"], ["Min. akvaryum", "54 L"], ["Huy", "Barışçıl; 8+ sürü"], ["Beslenme", "Etçil: yüzey yemleri, küçük böcekler, artemia"], ["Üreme", "Yumurtlayan"], ["Köken", "Brezilya, Venezuela, Peru (Rio Negro, Orinoco)"], ["Ömür", "3–5 yıl"], ["Özellikler", "Yüzey balığı, sıçrar"]]'::jsonb,array['blackwing hatchetfish','carnegiella marthae','marthae','balta balığı','hatchetfish']::text[],false,'Kapak şart; sıçrar. Yüzey bitkileriyle loş ortam sever.','[{"r": 500, "lat": 0, "lng": -65, "label": "Rio Negro ve Orinoco havzası"}]'::jsonb,null,'published'),
('pygocentrus-nattereri','Kırmızı Karınlı Pirana','Pygocentrus nattereri','characiformlar','fish','Orta','Grup hâlinde, yırtıcı','Kırmızı karnı ve keskin üçgen dişleriyle dünyanın en bilinen piranası. Ününün aksine akvaryumda ürkek bir balıktır; kalabalık grup hâlinde ve büyük tankta güven kazanır.','[["Yetişkin boy", "25–30 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "400 L (grup)"], ["Huy", "Grup hâlinde; diğer balıkları yer"], ["Beslenme", "Etçil: balık eti, karides, midye, pelet"], ["Üreme", "Yumurtlayan; erkek yuvayı korur"], ["Köken", "Güney Amerika (Amazon, Paraná, Paraguay havzaları)"], ["Ömür", "10–15 yıl"], ["Özellikler", "Keskin dişler, ürkek"]]'::jsonb,array['piranha','pirana','kırmızı karınlı pirana','red bellied piranha','pygocentrus nattereri','nattereri']::text[],false,'Tankta çalışırken dikkatli olun; ısırığı ciddi yaralanmaya yol açabilir. Tek tür tankta 5+ grup hâlinde tutulmalı.','[{"r": 900, "lat": -10, "lng": -60, "label": "Amazon havzası"}, {"r": 600, "lat": -20, "lng": -57, "label": "Paraná–Paraguay havzası"}]'::jsonb,null,'published'),
('serrasalmus-rhombeus','Siyah Pirana (Redeye Piranha)','Serrasalmus rhombeus','characiformlar','fish','Zor','Yalnız, çok saldırgan','Kırmızı gözleri ve yaşla koyulaşan gövdesiyle tanınan, dünyanın en iri piranalarından. Tür içi saldırgan olduğu için yalnız tutulur.','[["Yetişkin boy", "35–45 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "500 L"], ["Huy", "Yalnız tutulmalı"], ["Beslenme", "Etçil: balık eti, karides, midye"], ["Üreme", "Yumurtlayan"], ["Köken", "Amazon ve Orinoco havzaları, Guyana"], ["Ömür", "15+ yıl"], ["Özellikler", "Kırmızı gözler, iri pirana"]]'::jsonb,array['black piranha','redeye piranha','siyah pirana','serrasalmus rhombeus','rhombeus','pirana']::text[],false,'Isırığı ciddi yaralanmaya yol açabilir; tek başına tutulmalı.','[{"r": 900, "lat": -3, "lng": -60, "label": "Amazon havzası"}, {"r": 400, "lat": 6, "lng": -64, "label": "Orinoco havzası"}]'::jsonb,null,'published'),
('metynnis-lippincottianus','Benekli Gümüş Dolar','Metynnis lippincottianus','characiformlar','fish','Kolay','Barışçıl, sürü','Yuvarlak gümüşi gövdesindeki küçük koyu beneklerle tanınan, piranaların otçul akrabası. Sürü hâlinde yüzer ve akvaryumdaki yumuşak bitkileri hızla yer.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "300 L"], ["Huy", "Barışçıl; 5+ sürü"], ["Beslenme", "Otçul: sebze, spirulina, granül"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Amazon havzası (Brezilya)"], ["Ömür", "10 yıl"], ["Özellikler", "Otçul, bitki yer"]]'::jsonb,array['silver dollar','gümüş dolar','spotted silver dollar','metynnis lippincottianus','metynnis']::text[],false,'Su bitkilerini yer; plastik ya da dayanıklı bitkiler tercih edilmeli.','[{"r": 800, "lat": -4, "lng": -58, "label": "Orta ve aşağı Amazon"}]'::jsonb,null,'published'),
('myloplus-rubripinnis','Kırmızı Kancalı Gümüş Dolar (Red Hook)','Myloplus rubripinnis','characiformlar','fish','Orta','Barışçıl, sürü','Erkeklerinin anal yüzgecinde kırmızı bir "kanca" bulunan iri gümüş dolar. Piranaların otçul akrabasıdır; büyük tank ve sürü hâlinde tutulmalıdır.','[["Yetişkin boy", "20–25 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "500 L"], ["Huy", "Barışçıl; 5+ sürü"], ["Beslenme", "Otçul: sebze, meyve, spirulina"], ["Üreme", "Yumurtlayan"], ["Köken", "Amazon havzası, Guyana ve Orinoco"], ["Ömür", "10+ yıl"], ["Özellikler", "Kırmızı kanca yüzgeç"]]'::jsonb,array['red hook','red hook silver dollar','myloplus rubripinnis','myleus rubripinnis','gümüş dolar']::text[],false,'Su bitkilerini yer; çok büyük tank gerekir.','[{"r": 800, "lat": -2, "lng": -60, "label": "Amazon havzası"}, {"r": 400, "lat": 5, "lng": -58, "label": "Guyana"}]'::jsonb,'Eski adı Myleus rubripinnis; hobide hâlâ çoğunlukla bu adla bilinir.','published'),
('piaractus-brachypomus','Kırmızı Göğüslü Pacu','Piaractus brachypomus','characiformlar','fish','Zor','Barışçıl ama dev','Gençken kırmızı göğsüyle pirana sanılan, ancak otçul olan dev bir karasin. 80 cm''yi aşabilir; küçük boyda satılması nedeniyle en sık yanlış alınan akvaryum balıklarından biridir.','[["Yetişkin boy", "70–90 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "3000 L+"], ["Huy", "Barışçıl; büyük olduğu için tek tür"], ["Beslenme", "Otçul: meyve, sebze, iri pelet"], ["Üreme", "Yumurtlayan (akvaryumda kaydı yok)"], ["Köken", "Amazon ve Orinoco havzaları"], ["Ömür", "20+ yıl"], ["Özellikler", "Dev boy, insan dişine benzer dişler"]]'::jsonb,array['pacu','red bellied pacu','kırmızı göğüslü pacu','piaractus brachypomus','piaractus']::text[],false,'Ev akvaryumu için uygun değildir; çok hızlı büyür. Asla doğaya bırakılmamalı.','[{"r": 900, "lat": -4, "lng": -62, "label": "Amazon havzası"}, {"r": 400, "lat": 7, "lng": -66, "label": "Orinoco havzası"}]'::jsonb,'Hobide Colossoma macropomum (siyah pacu) ile sık karıştırılır.','published'),
('corydoras-elegans','Elegans Corydoras','Corydoras elegans','kedi-baliklari','fish','Kolay','Barışçıl, grup hâlinde','Diğer corydorasların aksine sık sık orta su katmanlarında da yüzen, gövdesinde koyu yatay çizgiler bulunan küçük bir corydoras. Dayanıklıdır ve kalabalık grupta çok hareketlidir.','[["Yetişkin boy", "5–6 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 6+ grup"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan (yumurtaları bitkilere yapıştırır)"], ["Köken", "Brezilya, Peru, Ekvador (yukarı Amazon)"], ["Ömür", "5–10 yıl"], ["Özellikler", "Orta suda da yüzer"]]'::jsonb,array['corydoras elegans','elegans','gastrodermus elegans','elegant cory','corydoras','çöpçü']::text[],false,'Kum zemin önerilir.','[{"r": 600, "lat": -4, "lng": -71, "label": "Yukarı Amazon havzası"}]'::jsonb,'2024''te yayımlanan Corydoras revizyonuyla Gastrodermus cinsine taşındı; güncel kaynaklarda Gastrodermus elegans olarak geçer.','published'),
('brochis-robineae','Bayrak Kuyruklu Corydoras (Flagtail Cory)','Brochis robineae','kedi-baliklari','fish','Kolay','Barışçıl, grup hâlinde','Kuyruk yüzgecindeki siyah-beyaz yatay çizgilerle bayrak gibi görünen, Rio Negro havzasından gelen bir corydoras. Uzun burunlu ve narin yapılıdır.','[["Yetişkin boy", "6–7 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl; 6+ grup"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan"], ["Köken", "Brezilya, Rio Negro havzası"], ["Ömür", "5–10 yıl"], ["Özellikler", "Çizgili bayrak kuyruk"]]'::jsonb,array['flagtail cory','bayrak kuyruklu corydoras','brochis robineae','corydoras robineae','robineae','corydoras','çöpçü']::text[],false,'Kum zemin önerilir.','[{"r": 300, "lat": -0.5, "lng": -64, "label": "Orta Rio Negro"}]'::jsonb,'Eski adı Corydoras robineae; 2024 revizyonuyla Brochis cinsine taşındı.','published'),
('brochis-haraldschultzi','Haraldschultzi Corydoras','Brochis haraldschultzi','kedi-baliklari','fish','Orta','Barışçıl, grup hâlinde','Uzun burnu ve gövdesindeki ağ benzeri koyu desenle tanınan, Brezilya''nın Guaporé havzasından gelen iri bir corydoras. Sterbai''ye benzer ama burnu daha uzundur.','[["Yetişkin boy", "6–7 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl; 6+ grup"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan"], ["Köken", "Brezilya, Rio Guaporé havzası"], ["Ömür", "5–10 yıl"], ["Özellikler", "Uzun burun, ağ deseni"]]'::jsonb,array['haraldschultzi','corydoras haraldschultzi','brochis haraldschultzi','corydoras','çöpçü']::text[],false,'Kum zemin önerilir.','[{"r": 300, "lat": -12.5, "lng": -63, "label": "Rio Guaporé havzası"}]'::jsonb,'Eski adı Corydoras haraldschultzi; 2024 revizyonuyla Brochis cinsine taşındı.','published'),
('dianema-urostriatum','Bayrak Kuyruklu Porthole Kedi Balığı','Dianema urostriatum','kedi-baliklari','fish','Kolay','Barışçıl, grup','Kuyruk yüzgecindeki siyah-beyaz çizgilerle tanınan, corydorasların büyük akrabası. Dipte değil, genellikle orta su katmanında asılı durur; sakin topluluk tanklarına uygundur.','[["Yetişkin boy", "10–12 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl; 4+ grup"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Köpük yuvası yapar"], ["Köken", "Brezilya, orta Amazon (Manaus çevresi)"], ["Ömür", "10 yıl"], ["Özellikler", "Çizgili kuyruk, orta suda yüzer"]]'::jsonb,array['flagtail porthole catfish','dianema urostriatum','dianema','porthole catfish']::text[],false,'','[{"r": 300, "lat": -3, "lng": -60, "label": "Manaus çevresi"}]'::jsonb,null,'published'),
('megalechis-thoracata','Hoplo Kedi Balığı','Megalechis thoracata','kedi-baliklari','fish','Kolay','Barışçıl','Kalın zırh plakaları ve dayanıklılığıyla bilinen, yüzeyden hava solayabilen bir kedi balığı. Erkek, yüzeye köpük yuvası yapar ve yumurtaları korur.','[["Yetişkin boy", "12–15 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl; üremede erkek bölgeci"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Köpük yuvası yapar; erkek korur"], ["Köken", "Güney Amerika (Amazon, Orinoco, Guyana)"], ["Ömür", "10+ yıl"], ["Özellikler", "Zırhlı, hava solur"]]'::jsonb,array['hoplo','hoplo catfish','megalechis thoracata','hoplosternum thoracatum','thoracata']::text[],false,'','[{"r": 900, "lat": -3, "lng": -62, "label": "Amazon havzası"}, {"r": 400, "lat": 6, "lng": -60, "label": "Orinoco ve Guyana"}]'::jsonb,'Eski adı Hoplosternum thoracatum.','published'),
('leiarius-pictus','Yelken Yüzgeçli Pim (Sailfin Pim)','Leiarius pictus','kedi-baliklari','fish','Zor','Yırtıcı','Çok yüksek sırt yüzgeci ve benekli deseniyle tanınan iri bir Pimelodid. Gece aktiftir; 60 cm''ye ulaşabilir ve ağzına sığan her balığı yer.','[["Yetişkin boy", "50–60 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "1500 L"], ["Huy", "Yırtıcı; büyük balıklarla tutulabilir"], ["Beslenme", "Etçil: balık eti, karides, iri pelet"], ["Üreme", "Yumurtlayan (akvaryumda kaydı yok)"], ["Köken", "Amazon ve Orinoco havzaları"], ["Ömür", "15+ yıl"], ["Özellikler", "Yüksek sırt yüzgeci"]]'::jsonb,array['sailfin pim','leiarius pictus','leiarius','pimelodid','yelken yüzgeçli']::text[],false,'Çok büyük tank gerekir; küçük balıkları yer.','[{"r": 900, "lat": -3, "lng": -66, "label": "Batı Amazon havzası"}, {"r": 400, "lat": 6, "lng": -66, "label": "Orinoco havzası"}]'::jsonb,null,'published'),
('sorubim-lima','Ördek Gagalı Kedi Balığı (Shovelnose Catfish)','Sorubim lima','kedi-baliklari','fish','Zor','Yırtıcı, barışçıl türlere karşı','Yassı, ördek gagasına benzeyen ağzı ve gövdesi boyunca uzanan siyah bandıyla tanınan bir Pimelodid. Bitkiler arasında baş aşağı asılı durarak avını bekler.','[["Yetişkin boy", "45–55 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "800 L"], ["Huy", "Yırtıcı; tür içi grup hâlinde tutulabilir"], ["Beslenme", "Etçil: balık eti, karides, iri pelet"], ["Üreme", "Yumurtlayan (akvaryumda kaydı yok)"], ["Köken", "Güney Amerika (Amazon, Orinoco, Paraná)"], ["Ömür", "15+ yıl"], ["Özellikler", "Ördek gagası ağız"]]'::jsonb,array['shovelnose catfish','duckbill catfish','ördek gagalı','sorubim lima','sorubim']::text[],false,'Ağzına sığan balıkları yer; büyük tank gerekir.','[{"r": 900, "lat": -5, "lng": -62, "label": "Amazon havzası"}, {"r": 600, "lat": -20, "lng": -58, "label": "Paraná–Paraguay havzası"}]'::jsonb,null,'published'),
('synodontis-angelicus','Polka Noktalı Synodontis (Angelicus)','Synodontis angelicus','kedi-baliklari','fish','Orta','Barışçıl, gece aktif','Gençken koyu mor zemin üzerindeki beyaz-sarı beneklerle Synodontis''lerin en gösterişlisi sayılan Kongo havzası balığı. Yaşla benekler küçülür; gece aktiftir.','[["Yetişkin boy", "20–25 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "250 L"], ["Huy", "Barışçıl; tür içi itişebilir"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan (akvaryumda nadir)"], ["Köken", "Kongo havzası (KDC, Kamerun)"], ["Ömür", "15+ yıl"], ["Özellikler", "Polka noktalı desen"]]'::jsonb,array['polka dot synodontis','synodontis angelicus','angelicus','synodontis','upside down catfish']::text[],false,'','[{"r": 700, "lat": -1, "lng": 20, "label": "Kongo havzası"}]'::jsonb,null,'published'),
('synodontis-decorus','Synodontis decorus','Synodontis decorus','kedi-baliklari','fish','Orta','Barışçıl, gece aktif','Benekli gövdesi ve yaşla sırt yüzgecinden uzayan uzun iplikle tanınan iri bir Kongo Synodontis''i. Sakin büyük balıklarla iyi geçinir.','[["Yetişkin boy", "25–30 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "300 L"], ["Huy", "Barışçıl; tür içi itişebilir"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan (akvaryumda nadir)"], ["Köken", "Kongo havzası"], ["Ömür", "15+ yıl"], ["Özellikler", "Uzun sırt yüzgeci ipliği"]]'::jsonb,array['synodontis decorus','clown squeaker','decorus','synodontis']::text[],false,'','[{"r": 700, "lat": -1, "lng": 20, "label": "Kongo havzası"}]'::jsonb,null,'published')
