values
('synodontis-flavitaeniatus','Sarı Çizgili Synodontis','Synodontis flavitaeniatus','kedi-baliklari','fish','Orta','Barışçıl, gece aktif','Kahverengi gövdesindeki parlak sarı yatay çizgilerle diğer Synodontis''lerden hemen ayırt edilen, Kongo havzasından gelen orta boy bir tür.','[["Yetişkin boy", "15–20 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl; tür içi itişebilir"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan (akvaryumda nadir)"], ["Köken", "KDC, Kongo havzası (Malebo Havuzu çevresi)"], ["Ömür", "15+ yıl"], ["Özellikler", "Sarı çizgiler"]]'::jsonb,array['synodontis flavitaeniatus','flavitaeniatus','orange striped squeaker','synodontis']::text[],false,'','[{"r": 400, "lat": -3, "lng": 17, "label": "Orta Kongo havzası"}]'::jsonb,null,'published'),
('pangio-myersi','Dev Kuhli Loach (Myers Kuhli)','Pangio myersi','loachlar','fish','Kolay','Barışçıl, grup hâlinde','Turuncu zemin üzerindeki kalın siyah halkalarıyla Kuhli loachların en irisi. Gece aktiftir; yumuşak kumda saklanır ve grup hâlinde daha cesur olur.','[["Yetişkin boy", "10–12 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl; 5+ grup"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan (akvaryumda nadir)"], ["Köken", "Tayland, Laos, Vietnam, Kamboçya (Mekong havzası)"], ["Ömür", "10 yıl"], ["Özellikler", "Kalın siyah halkalar"]]'::jsonb,array['giant kuhli','dev kuhli','myers kuhli','pangio myersi','kuhli','loach']::text[],false,'Filtre girişlerine kaçabilir; giriş süngerle kapatılmalı.','[{"r": 500, "lat": 14, "lng": 104, "label": "Mekong havzası"}]'::jsonb,null,'published'),
('lepomis-gibbosus','Güneş Balığı (Pumpkinseed)','Lepomis gibbosus','diger-baliklar','fish','Kolay','Üremede bölgeci','Turuncu göğsü, mavi-yeşil dalgalı yüz çizgileri ve solungaç kapağındaki kırmızı lekesiyle tanınan Kuzey Amerika güneş balığı. Soğuk suya dayanıklıdır; Avrupa ve Türkiye''de doğaya yayılmış istilacı bir türdür.','[["Yetişkin boy", "15–20 cm"], ["Sıcaklık", "4–25 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "200 L"], ["Huy", "Üremede bölgeci; küçük balıkları yer"], ["Beslenme", "Etçil: solucan, karides, donuk yem"], ["Üreme", "Yumurtlayan; erkek yuva kazar ve korur"], ["Köken", "Kuzey Amerika (doğu); Avrupa ve Türkiye''de istilacı"], ["Ömür", "8–12 yıl"], ["Özellikler", "Soğuk su, havuza uygun"]]'::jsonb,array['pumpkinseed','güneş balığı','lepomis gibbosus','lepomis','sunfish']::text[],false,'İstilacı bir türdür; doğaya, göle ya da dereye asla bırakılmamalı. Bazı ülkelerde bulundurulması yasaktır.','[{"r": 1200, "lat": 43, "lng": -78, "label": "Kuzeydoğu ABD ve Güneydoğu Kanada"}]'::jsonb,null,'published'),
('mastacembelus-armatus','Lastik İzli Yılan Balığı (Tire Track Eel)','Mastacembelus armatus','diger-baliklar','fish','Orta','Barışçıl ama küçük balıkları yer','Gövdesindeki zikzak koyu desen lastik izine benzeyen, Güney ve Güneydoğu Asya''dan gelen iri bir dikenli yılan balığı. Kuma gömülerek saklanır; sahibini tanıyıp elden yem alabilir.','[["Yetişkin boy", "50–75 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "500 L"], ["Huy", "Barışçıl; ağzına sığanı yer"], ["Beslenme", "Etçil: solucan, karides, kan kurdu"], ["Üreme", "Yumurtlayan (akvaryumda nadir)"], ["Köken", "Hindistan, Sri Lanka, Güneydoğu Asya"], ["Ömür", "15+ yıl"], ["Özellikler", "Kuma gömülür"]]'::jsonb,array['tire track eel','lastik izli yılan balığı','mastacembelus armatus','dikenli yılan balığı','spiny eel']::text[],false,'Yumuşak kum zemin şart; kapak sıkı olmalı, en küçük açıklıktan kaçabilir.','[{"r": 1200, "lat": 20, "lng": 90, "label": "Güney ve Güneydoğu Asya"}]'::jsonb,null,'published'),
('macrognathus-aculeatus','Yaprak Kuyruklu Yılan Balığı','Macrognathus aculeatus','diger-baliklar','fish','Orta','Barışçıl','Kuyruğa yakın sırtında birkaç gözlü leke bulunan, sivri burunlu küçük bir dikenli yılan balığı. Kumda gömülü yaşar; canlı ve donuk yemlerle beslenir.','[["Yetişkin boy", "25–35 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl; çok küçük balıkları yiyebilir"], ["Beslenme", "Etçil: kan kurdu, karides, solucan"], ["Üreme", "Yumurtlayan"], ["Köken", "Güneydoğu Asya (Tayland, Malezya, Endonezya)"], ["Ömür", "8–10 yıl"], ["Özellikler", "Gözlü sırt lekeleri"]]'::jsonb,array['peacock eel','macrognathus aculeatus','dikenli yılan balığı','spiny eel','macrognathus']::text[],false,'Yumuşak kum zemin ve sıkı kapak şart.','[{"r": 900, "lat": 5, "lng": 105, "label": "Güneydoğu Asya"}]'::jsonb,null,'published'),
('tetraodon-miurus','Kongo Balonu (Tetraodon miurus)','Tetraodon miurus','diger-baliklar','fish','Zor','Pusucu, yalnız','Kuma gömülüp yalnızca gözlerini dışarıda bırakarak avını pusuda bekleyen, Kongo Nehri''nin hızlı akıntılı bölgelerinden gelen bir balon. Rengi kırmızımsıdan kahveye değişebilir.','[["Yetişkin boy", "12–15 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "100 L"], ["Huy", "Yalnız tutulmalı"], ["Beslenme", "Etçil: balık eti, karides, salyangoz"], ["Üreme", "Yumurtlayan (akvaryumda kaydı yok)"], ["Köken", "KDC, Kongo Nehri"], ["Ömür", "10 yıl"], ["Özellikler", "Kuma gömülen pusucu"]]'::jsonb,array['tetraodon miurus','miurus','congo puffer','kongo balonu','balon balığı','puffer']::text[],false,'Ağzına sığan her balığı yer; yalnız tutulmalı. İnce kum zemin şart.','[{"r": 500, "lat": -3, "lng": 18, "label": "Kongo Nehri"}]'::jsonb,null,'published'),
('garra-rufa','Doktor Balığı (Garra rufa)','Garra rufa','sazangiller','fish','Kolay','Barışçıl, grup','Türkiye''nin de doğal türlerinden biri olan, Dicle-Fırat havzası ve Kangal kaplıcalarıyla ünlü küçük bir sazangil. Taşlardaki algleri kazıyarak beslenir; serin ve akıntılı suyu sever.','[["Yetişkin boy", "10–14 cm"], ["Sıcaklık", "18–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl; 5+ grup"], ["Beslenme", "Hepçil: alg, sebze, batan granül"], ["Üreme", "Yumurtlayan"], ["Köken", "Türkiye, Suriye, Irak, İran (Dicle–Fırat havzası)"], ["Ömür", "5–8 yıl"], ["Özellikler", "Türkiye''nin doğal türü, alg yer"]]'::jsonb,array['doktor balığı','doctor fish','garra rufa','kangal balığı','kaplıca balığı','garra']::text[],false,'Doğadan toplanmamalı; yalnızca üretim bireyleri tercih edilmeli. Akıntılı, oksijeni bol su ister.','[{"r": 500, "lat": 37.5, "lng": 40, "label": "Dicle–Fırat havzası"}, {"r": 50, "lat": 39.2, "lng": 37.4, "label": "Kangal Balıklı Kaplıca"}]'::jsonb,null,'published'),
('tanichthys-micagemmae','Vietnam Kardinal Minnow','Tanichthys micagemmae','sazangiller','fish','Kolay','Barışçıl, sürü','White Cloud''un (T. albonubes) Vietnam''daki küçük akrabası; gövdesinde parlak turuncu ve mavi şeritler bulunur. Serin suya dayanıklıdır; nano akvaryumlara uygundur.','[["Yetişkin boy", "2.5–3 cm"], ["Sıcaklık", "18–24 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "30 L"], ["Huy", "Barışçıl; 8+ sürü"], ["Beslenme", "Hepçil: mikro granül, donuk yem"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Orta Vietnam"], ["Ömür", "3–4 yıl"], ["Özellikler", "Nano, serin suya dayanıklı"]]'::jsonb,array['vietnamese cardinal minnow','tanichthys micagemmae','micagemmae','white cloud','tanichthys']::text[],false,'','[{"r": 100, "lat": 16.5, "lng": 107, "label": "Orta Vietnam"}]'::jsonb,null,'published'),
('microrasbora-rubescens','Kırmızı Mikro Rasbora','Microrasbora rubescens','danio-rasboralar','fish','Orta','Barışçıl, sürü','Myanmar''daki Inle Gölü''ne özgü, erkekleri üreme döneminde kırmızımsı tonlara bürünen küçük bir sazangil. Sert ve serin suyu sever; Sawbwa barb ile aynı gölde yaşar.','[["Yetişkin boy", "3 cm"], ["Sıcaklık", "20–25 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl; 8+ sürü"], ["Beslenme", "Hepçil: mikro granül, donuk yem"], ["Üreme", "Yumurtlayan"], ["Köken", "Myanmar, Inle Gölü"], ["Ömür", "3 yıl"], ["Özellikler", "Nano, sert su"]]'::jsonb,array['microrasbora rubescens','rubescens','red dwarf rasbora','inle','rasbora']::text[],false,'Doğal yaşam alanı tehdit altındadır; üretim bireyleri tercih edilmeli.','[{"r": 30, "lat": 20.55, "lng": 96.9, "label": "Inle Gölü"}]'::jsonb,null,'published'),
('melanotaenia-splendida','Splendida Gökkuşağı','Melanotaenia splendida','gokkusaklari','fish','Kolay','Barışçıl, sürü','Avustralya ve Yeni Gine''de geniş bir alana yayılmış, birçok alt türü ve lokalitesi olan bir gökkuşağı balığı. Gövdesinde kırmızı-mavi ince çizgiler ve kırmızı benekli yüzgeçler bulunur.','[["Yetişkin boy", "10–12 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl; 6+ sürü"], ["Beslenme", "Hepçil: granül, donuk yem, sebze"], ["Üreme", "Yumurtlayan (yumurtaları bitkilere yapıştırır)"], ["Köken", "Kuzey Avustralya ve Yeni Gine"], ["Ömür", "5–8 yıl"], ["Özellikler", "Çok lokaliteli gökkuşağı"]]'::jsonb,array['splendida','melanotaenia splendida','eastern rainbowfish','gökkuşağı balığı','rainbowfish']::text[],false,'','[{"r": 900, "lat": -16, "lng": 140, "label": "Kuzey Avustralya"}, {"r": 600, "lat": -7, "lng": 142, "label": "Güney Yeni Gine"}]'::jsonb,null,'published'),
('scatophagus-tetracanthus','Afrika Scatı','Scatophagus tetracanthus','aci-su','fish','Orta','Barışçıl, grup','Gümüşi gövdesinde dikey siyah bantlar bulunan, Doğu Afrika kıyılarının acı sularından gelen bir scat. Gençken tatlı suda yaşayabilir, erişkinlikte acı ya da deniz suyu ister.','[["Yetişkin boy", "20–30 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "300 L"], ["Huy", "Barışçıl; 4+ grup"], ["Beslenme", "Hepçil: sebze, granül, donuk yem"], ["Üreme", "Yumurtlayan (denizde)"], ["Köken", "Doğu Afrika kıyıları (Kenya–Güney Afrika) ve Madagaskar"], ["Ömür", "10+ yıl"], ["Özellikler", "Bantlı scat"]]'::jsonb,array['african scat','afrika scatı','scatophagus tetracanthus','tetracanthus','scat']::text[],false,'Erişkinler acı ya da deniz suyu ister. Su bitkilerini yer.','[{"r": 900, "lat": -10, "lng": 40, "label": "Doğu Afrika kıyıları"}]'::jsonb,null,'published'),
('selenotoca-multifasciata','Gümüş Scat (Silver Scat)','Selenotoca multifasciata','aci-su','fish','Orta','Barışçıl, grup','Gümüşi gövdesindeki ince dikey çizgiler ve beneklerle tanınan, Avustralya ve Yeni Gine kıyılarından gelen bir scat. Erişkinlikte acı ya da deniz suyu ister.','[["Yetişkin boy", "25–35 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "400 L"], ["Huy", "Barışçıl; 4+ grup"], ["Beslenme", "Hepçil: sebze, granül, donuk yem"], ["Üreme", "Yumurtlayan (denizde)"], ["Köken", "Kuzey Avustralya, Yeni Gine, Yeni Kaledonya"], ["Ömür", "10+ yıl"], ["Özellikler", "Gümüşi, çizgili scat"]]'::jsonb,array['silver scat','gümüş scat','selenotoca multifasciata','selenotoca','scat']::text[],false,'Erişkinler acı ya da deniz suyu ister. Su bitkilerini yer.','[{"r": 1200, "lat": -15, "lng": 145, "label": "Kuzey Avustralya ve Yeni Gine kıyıları"}]'::jsonb,null,'published'),
('potamotrygon-leopoldi','Siyah Elmas Vatoz (Black Diamond Ray)','Potamotrygon leopoldi','ilkel-siradisi-baliklar','fish','Zor','Barışçıl, dip yırtıcısı','Simsiyah zemin üzerindeki beyaz beneklerle tatlı su vatozlarının en gösterişlilerinden biri. Yalnızca Brezilya''daki Xingu Nehri''nde yaşar; çok büyük tank ve kusursuz su kalitesi ister.','[["Yetişkin boy", "50–60 cm (disk çapı)"], ["Sıcaklık", "25–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "1500 L"], ["Huy", "Barışçıl; dip balıklarını avlar"], ["Beslenme", "Etçil: karides, midye, solucan, balık eti"], ["Üreme", "Canlı doğurur"], ["Köken", "Brezilya, Rio Xingu"], ["Ömür", "15+ yıl"], ["Özellikler", "Zehirli kuyruk dikeni"]]'::jsonb,array['black diamond stingray','siyah elmas vatoz','potamotrygon leopoldi','leopoldi','vatoz','tatlı su vatozu']::text[],true,'Kuyruğundaki zehirli diken çok acı ve tehlikeli yaralara yol açar. Nitrata çok hassastır; güçlü filtre ve sık su değişimi şart. Bazı ülkelerde bulundurulması izne tabidir.','[{"r": 400, "lat": -5, "lng": -52.5, "label": "Rio Xingu"}]'::jsonb,null,'published'),
('scleropages-jardinii','Avustralya Arowanası (Jardini)','Scleropages jardinii','ilkel-siradisi-baliklar','fish','Zor','Saldırgan, yalnız','Gövdesindeki kırmızı-altın benekli pullarıyla tanınan, Kuzey Avustralya ve Yeni Gine''den gelen bir arowana. Diğer arowanalardan daha saldırgandır ve genellikle yalnız tutulur.','[["Yetişkin boy", "60–90 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "1000 L"], ["Huy", "Saldırgan; yalnız tutulmalı"], ["Beslenme", "Etçil: balık eti, karides, böcek, iri pelet"], ["Üreme", "Ağızda kuluçka (dişi)"], ["Köken", "Kuzey Avustralya ve Yeni Gine"], ["Ömür", "15+ yıl"], ["Özellikler", "Benekli pullar, güçlü zıplar"]]'::jsonb,array['jardini arowana','australian arowana','avustralya arowanası','scleropages jardinii','arowana']::text[],false,'Çok güçlü zıplar; ağır ve sıkı kapak şart.','[{"r": 700, "lat": -14, "lng": 136, "label": "Kuzey Avustralya"}, {"r": 400, "lat": -8, "lng": 142, "label": "Güney Yeni Gine"}]'::jsonb,null,'published'),
('trichopodus-pectoralis','Yılan Derisi Gurami (Snakeskin Gourami)','Trichopodus pectoralis','labirentliler','fish','Kolay','Barışçıl','Gövdesindeki zikzak desenli koyu çizgiyle yılan derisini andıran, iri ama sakin bir gurami. Güneydoğu Asya''da besin balığı olarak da yetiştirilir; dayanıklıdır.','[["Yetişkin boy", "20–25 cm"], ["Sıcaklık", "22–30 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "200 L"], ["Huy", "Barışçıl"], ["Beslenme", "Hepçil: granül, sebze, donuk yem"], ["Üreme", "Köpük yuvası yapar"], ["Köken", "Güneydoğu Asya (Mekong ve Chao Phraya havzaları)"], ["Ömür", "10 yıl"], ["Özellikler", "Dayanıklı iri gurami"]]'::jsonb,array['snakeskin gourami','yılan derisi gurami','trichopodus pectoralis','trichogaster pectoralis','gurami']::text[],false,'','[{"r": 700, "lat": 14, "lng": 103, "label": "Mekong ve Chao Phraya havzaları"}]'::jsonb,'Eski adı Trichogaster pectoralis.','published'),
('marisa-cornuarietis','Koç Boynuzu Elma Salyangozu (Marisa)','Marisa cornuarietis','salyangozlar','fish','Kolay','Barışçıl','Düz, koç boynuzu gibi kıvrılmış kabuğu ve koyu spiral çizgileriyle tanınan iri bir elma salyangozu. Çok obur bir otçuldur; su bitkilerini kısa sürede yiyebilir.','[["Yetişkin boy", "4–5 cm (kabuk)"], ["Sıcaklık", "21–28 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl"], ["Beslenme", "Otçul: sebze, alg tableti, bitkiler"], ["Üreme", "Yumurtlayan (yumurtalarını su altına bırakır)"], ["Köken", "Güney ve Orta Amerika (Venezuela, Kolombiya, Brezilya)"], ["Ömür", "2–3 yıl"], ["Özellikler", "Bitki yiyen elma salyangozu"]]'::jsonb,array['marisa','marisa cornuarietis','giant ramshorn','koç boynuzu salyangoz','elma salyangozu','salyangoz']::text[],false,'Bitkili akvaryumlarda bitkileri yer. Doğaya bırakılmamalı; birçok ülkede istilacıdır.','[{"r": 700, "lat": 7, "lng": -66, "label": "Venezuela ve Kolombiya"}, {"r": 500, "lat": -8, "lng": -45, "label": "Kuzeydoğu Brezilya"}]'::jsonb,null,'published')
